-- ============================================================
-- SEED EXT 3: Módulo 03 — Past Simple (ex 181-240)
-- Novos tópicos: PS vs PP em narrativa, PS passivo avançado,
-- PS com adv. de tempo, verbos irregulares avançados, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'past-simple';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo past-simple não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: past simple vs present perfect
  (cid,31,181,'multiple_choice','What is the key difference between "Scientists discovered X in 1953" and "Scientists have discovered X"?','"Discovered" (PS) = completed event at a specific past time. "Have discovered" (PP) = relevant to the present, no specific time.','["They are identical","''Discovered'' is informal; ''have discovered'' is formal","''Discovered'' (PS) = completed event at a specific past time. ''Have discovered'' (PP) = relevant to the present, no specific time.","Past simple is always more formal than present perfect"]','PS = specific time; PP = relevance to now. "In 1953" forces past simple.','hard'),
  (cid,31,182,'gap_fill','Marie Curie _____ (win) the Nobel Prize in Chemistry in 1911. She _____ (also/win) the Nobel Prize in Physics in 1903.','won / also won',NULL,'"Won" = past simple for specific, completed historical events with dates.','easy'),
  (cid,31,183,'gap_fill','The study _____ (publish/passive) in 2019 and _____ (have) a significant impact on subsequent research.','was published / had',NULL,'Past simple for completed historical sequence in academic context.','medium'),
  (cid,31,184,'multiple_choice','Which sentence is INCORRECT?','Researchers have published the results last year.','["Researchers published the results last year (correct — specific time).","Researchers have published several relevant studies on this topic (correct — no specific time).","Researchers have published the results last year.","The results were published in 2022 (correct — passive past simple)."]','"Have published" + specific time ("last year") = error. Use past simple with time references.','hard'),
  (cid,31,185,'gap_fill','The financial crisis of 2008 _____ (trigger) widespread bank failures and _____ (lead) to the deepest recession since the Great Depression.','triggered / led',NULL,'Past simple for completed historical sequence.','easy'),

  -- BLOCK 32: PS passivo em escrita acadêmica
  (cid,32,186,'gap_fill','The samples _____ (collect/passive) over a period of six months and _____ (store/passive) at -80°C until analysis.','were collected / were stored',NULL,'Passive past simple for describing research methodology.','medium'),
  (cid,32,187,'multiple_choice','Which sentence uses past passive CORRECTLY in a research methods section?','Participants were recruited through online advertisements and social media platforms.','["Participants recruited through online advertisements.","Participants were recruiting through online advertisements.","Participants were recruited through online advertisements and social media platforms.","Participants have been recruited through online advertisements."]','"Were + past participle" = past passive for completed methodological steps.','easy'),
  (cid,32,188,'gap_fill','Statistical analyses _____ (conduct/passive) using SPSS version 26, and results _____ (consider/passive) significant at p < 0.05.','were conducted / were considered',NULL,'Methods section: past passive for procedures already completed.','medium'),
  (cid,32,189,'multiple_choice','Why is past passive preferred over active in methods sections?','The process (what was done) is more important than who did it.','["It is always grammatically required","Past passive is shorter","The process (what was done) is more important than who did it.","Active voice is prohibited in methods sections"]','Methods sections focus on the procedure: past passive = process-oriented.','medium'),
  (cid,32,190,'gap_fill','Informed consent _____ (obtain/passive) from all participants, and the study _____ (approve/passive) by the institutional ethics committee.','was obtained / was approved',NULL,'Ethics and consent: past passive for completed administrative procedures.','easy'),

  -- BLOCK 33: PS com advérbios de tempo
  (cid,33,191,'gap_fill','The expedition _____ (depart) three years ago and only _____ (return) last autumn.','departed / returned',NULL,'"Ago" and "last autumn" = specific past time markers → past simple.','easy'),
  (cid,33,192,'multiple_choice','Which time expression forces past simple (NOT present perfect)?','Yesterday, scientists announced a breakthrough in quantum computing.','["Scientists have recently announced a breakthrough in quantum computing.","Scientists have just announced a breakthrough.","Yesterday, scientists announced a breakthrough in quantum computing.","Scientists have already announced a breakthrough."]','"Yesterday" = specific past time → past simple only. Cannot use present perfect with "yesterday."','easy'),
  (cid,33,193,'gap_fill','In 1969, Apollo 11 _____ (land) on the moon. The mission _____ (last) eight days in total.','landed / lasted',NULL,'Specific past date → past simple throughout the narrative.','easy'),
  (cid,33,194,'multiple_choice','Which adverb is INCOMPATIBLE with past simple?','The researchers have just published their findings recently.','["The researchers published their findings two weeks ago (correct).","The researchers published their findings in 2021 (correct).","The researchers published their findings last month (correct).","The researchers have just published their findings recently."]','"Have just published" = present perfect (not past simple). "Just" + PP = recent relevance.','medium'),
  (cid,33,195,'gap_fill','The government _____ (implement) the new policy in January 2022, and within six months, infection rates _____ (fall) by 30%.','implemented / fell',NULL,'Sequence of completed past events with specific timeframe.','medium'),

  -- BLOCK 34: verbos irregulares avançados em contexto
  (cid,34,196,'gap_fill','The board _____ (forsake) traditional values in pursuit of short-term profit.','forsook',NULL,'"Forsake → forsook → forsaken" = irregular past simple (advanced).','hard'),
  (cid,34,197,'multiple_choice','Which row of irregular verbs is ALL CORRECT?','arise – arose – arisen; bind – bound – bound; shrink – shrank – shrunk.','["arise – arised – arisen; bind – bound – bound; shrink – shrank – shrunk","arise – arose – arisen; bind – bonded – bound; shrink – shrank – shrunk","arise – arose – arisen; bind – bound – bound; shrink – shrank – shrunk.","arise – arose – arose; bind – bound – bound; shrink – shrunk – shrunk"]','arise/arose/arisen; bind/bound/bound; shrink/shrank/shrunk = all correct irregular forms.','hard'),
  (cid,34,198,'gap_fill','The river _____ (overflow) its banks after weeks of heavy rainfall, and it _____ (bring) significant destruction to the surrounding settlements.','overflowed / brought',NULL,'"Overflow" = regular (overflowed). "Bring → brought" = irregular past simple.','hard'),
  (cid,34,199,'multiple_choice','Which sentence contains an INCORRECT irregular past simple?','The scientist catched a critical error in the data before publication.','["The committee chose a new director from a list of five candidates.","The researcher withdrew the paper after discovering a calculation error.","The scientist catched a critical error in the data before publication.","The experiment yielded unexpected but reproducible results."]','"Catched" is wrong. "Catch → caught."','medium'),

  -- BLOCK 35: TOEFL Reading
  (cid,35,200,'multiple_choice','[TOEFL Reading] "The Roman Empire collapsed in 476 CE, marking the end of classical antiquity in the Western world." Why past simple?','It describes a singular, completed historical event at a specific time.','["It is a scientific truth stated as present","The author is speculating about the past","It describes a singular, completed historical event at a specific time.","It is a repeated past habit"]','Specific historical date + completed event → past simple.','easy'),
  (cid,35,201,'gap_fill','[TOEFL Reading] "Data _____ (collect/passive) from 47 research sites across six continents and _____ (analyze/passive) using generalized linear models." Best forms?','were collected / were analyzed',NULL,'Methods section: past passive for completed research procedures.','medium'),
  (cid,35,202,'multiple_choice','[TOEFL Reading] "After the Berlin Wall fell in 1989, German reunification followed rapidly." The past simple in this sentence:','Describes a sequence of specific, completed historical events.','["Expresses a general truth","Describes a sequence of specific, completed historical events.","Refers to a habitual past action","Is incorrect — past perfect should be used"]','Past simple for two completed historical events in sequence.','easy'),
  (cid,35,203,'gap_fill','[TOEFL Reading] "The algorithm _____ (misclassify) 12% of cases in the first trial, a rate that _____ (improve) significantly in subsequent iterations." Best forms?','misclassified / improved',NULL,'Past simple for specific completed research events.','easy'),

  -- BLOCK 36: TOEFL Speaking
  (cid,36,204,'production','[TOEFL Speaking — 45s] Describe the key developments in the history of the internet using past simple and past passive (for events where the actor is less important than the process).','',NULL,'The internet originated in the late 1960s as a US military project called ARPANET. The World Wide Web was developed by Tim Berners-Lee in 1989 and was opened to the public in 1991, transforming what had been a niche academic tool into a global communication platform. During the 1990s, commercial internet services expanded rapidly, and browsers such as Netscape were developed that made the web accessible to non-technical users. Social media platforms emerged in the 2000s and fundamentally altered how people communicated and consumed information. The smartphone revolution, launched with the first iPhone in 2007, further accelerated internet adoption by untethering connectivity from desktop computers.','hard'),
  (cid,36,205,'production','[TOEFL Speaking — 45s] A reading discusses a major 20th-century environmental disaster. Discuss what happened, when, and what the consequences were. Use: past simple (active), past simple passive, irregular verbs, time adverbs.','',NULL,'The Chernobyl nuclear disaster occurred on April 26, 1986, when a safety test at Reactor No. 4 went catastrophically wrong. An explosion tore apart the reactor and sent a plume of radioactive material into the atmosphere over much of Europe. Soviet authorities initially downplayed the severity of the accident; news of the scale of the disaster leaked slowly in the days that followed. Approximately 350,000 people were evacuated from the affected zone, and the nearby city of Pripyat was abandoned permanently. Long-term cancer rates rose in affected populations, and the disaster dealt a severe blow to public trust in nuclear power that lasted for decades.','hard'),

  -- BLOCK 37: TOEFL Writing
  (cid,37,206,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "The causes and consequences of the 2008 global financial crisis." Use: past simple (active, ×4), past passive (×3), time adverbs (in 2008 / by 2009 / within months), irregular verbs (fell / rose / led / swept / froze).','',NULL,'The global financial crisis of 2008 arose from a convergence of deregulation, excessive risk-taking, and the proliferation of complex financial instruments that few regulators fully understood. When the US housing bubble burst in 2007, the value of mortgage-backed securities fell sharply, exposing the fragility of major financial institutions. In September 2008, Lehman Brothers — one of Wall Street''s largest investment banks — collapsed, and credit markets froze almost immediately. Within months, the crisis swept across global financial systems: stock markets fell sharply, unemployment rose rapidly, and the banking sector was stabilized only through massive government intervention. By 2009, trillions of dollars in public funds were committed to bailouts and stimulus programs in an attempt to prevent a depression. The crisis led to the most significant reform of financial regulation since the 1930s.','hard'),
  (cid,37,207,'production','[TOEFL Writing — Error Correction] Fix past simple errors: "Researchers have published their findings in 2020. The samples collected and analyzed manually. The committee have chosen a new director last week. The experiment shown unexpected results. The data was collected yesterday, so we haven''t analyzed it yet (correct — no fix needed)."','',NULL,'have published → published (specific time "in 2020" → past simple, not present perfect); The samples collected → The samples were collected (missing auxiliary ''were'' for passive past simple); have chosen → chose (specific time ''last week'' → past simple); shown → showed (show → showed in past simple; ''shown'' is past participle — needs ''have shown''); the final sentence is correct — no fix needed (past simple + present perfect both appropriate here).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
